public class Solution {
    public List<String> findDuplicates(List<String> ids) {
        Set<String> seen = new HashSet<>();
        Set<String> dup = new LinkedHashSet<>();
        for (String id : ids) if (!seen.add(id)) dup.add(id);
        return new ArrayList<>(dup);
    }
}

